-- SPEC D11 backstop follows core's `reduceNationalIds` again (#425, Q-17b). Core reads any punctuation, symbol or mark
-- between digit groups, keeps a figure that a currency marker leads or follows whole whatever its grouping, cuts a
-- 12-digit run that a dot and a digit follow, and counts digits of every script. SQL read a short list of separators,
-- a narrower amount rule and ASCII digits only, so it refused `Giá 123 456 789 012 VND` and accepted `cccd 079–123–456–789`.
--
-- Before the patterns look, the text is folded to a small alphabet: digits of every script become 0-9, a slash of any
-- width becomes `/`, a character core takes for a separator between digit groups becomes `~` (and `^` when only a
-- label makes it one), and a date, an amount and a price become `x`. The two character classes below are the ranges
-- core joins on, measured from the reducer itself; supabase/tests/national_id.test.sql sweeps every BMP character
-- against core's answer, so a Unicode change in either side fails there.
create or replace function private.blank_matches_once(p_text text, p_pattern text, p_flags text)
returns text
language sql
immutable
set search_path = ''
as $$
  with scanned as (
    select
      regexp_split_to_array(p_text, '(' || p_pattern || ')', p_flags) as pieces,
      array(select hit[1] from regexp_matches(p_text, '(' || p_pattern || ')', 'g' || p_flags) as hit) as hits
  )
  select coalesce(string_agg(piece || coalesce(repeat('x', length(hits[n])), ''), '' order by n), p_text)
  from scanned, unnest(pieces) with ordinality as piece_at(piece, n);
$$;

create or replace function private.holds_national_id(p_value jsonb)
